"""Authoring-only catalogue: 3 proposed generic-block designs per written theme.

Does not import regional_profiles or change any generation/runtime catalogue.
Rows: title | diagram grammar | suitable floors | bay metres | palette |
composition | entrance/base | crown | controlled variations.
"""
from pathlib import Path
import hashlib
import html
import json
import re

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'server/buildgen/catalog/environments.json'
OUT = ROOT / 'docs'
DESIGNS = {}


def region(key, rows):
    fields = ('name', 'grammar', 'floor_range', 'bay_range_m', 'palette',
              'composition', 'base_and_entry', 'roof_edge', 'variation')
    parsed = [line.strip().split('|') for line in rows.strip().splitlines() if line.strip()]
    assert len(parsed) == 3, key
    assert all(len(row) == len(fields) for row in parsed), key
    DESIGNS[key] = [dict(zip(fields, (v.strip() for v in row))) for row in parsed]


